CH("m1","Drei Sorten Leistungen","Präsentation 2 bis 6","Universal, Versicherung, Fürsorge",["msp"])
CH("m2","WMS: Antrag und Anspruch","Präsentation 7 bis 11","MA 40, Bedarfsgemeinschaft, Personenkreis",["msp"])
CH("m3","WMS: Geld und Rechnen","Präsentation 12 bis 19","Mindeststandards, Mietbeihilfe",["msp"])
CH("m4","WMS: Anrechnung","Präsentation 20 und 21","Einkommen, Vermögen, fiktiv",["msp"])
CH("m5","WMS: Pflichten und Kürzung","Präsentation 22 bis 26","Sperre, Ruhen, Rückforderung",["msp"])
CH("m6","Hilfe in der Not","Präsentation 27 und 33 bis 36","HibL, Energie, Sozialzentren",["msp"])
CH("m7","Wohnung sichern","Präsentation 28 bis 32","FAWOS, MA 11, MA 40, Wohnschirm",["msp"])
CH("m8","Wiener Wohnungslosenhilfe","Präsentation 39 bis 45","Housing First, Chancenhaus, mobeWO",["msp"])
CH("m9","Betreutes Konto","Präsentation 46 bis 56","Miete zuerst, Mensch entscheidet",["msp"])
CH("m10","Schulden erkennen","Präsentation 37, 38, 57 bis 61 und 67 bis 69","Gefährliche zuerst",["msp"])
